@startuml

class Customer {
  + Address : string
  + VATNumber : string
  + HeadOfficeAddress : string
}

class Product {
  + Name : string
  + StockLevel : int
}

class Order {
  + OrderDate : date
  + PaymentDate : date
  + IsPaid : boolean
}

class OrderLine {
  + Quantity : int
}

class Invoice {
  + InvoiceDate : date
}

class Delivery {
  + Status : string
  + PackingDate : date
  + ShippingDate : date
  + ReceivedDate : date
}

class DeliveryLine {
}

class DeliveryService {
  + Name : string
}

Customer "1" -- "*" Order : places
Customer "1" -- "*" Invoice : receives
Order "1" *-- "1..*" OrderLine : contains
OrderLine "1" -- "*" DeliveryLine : partOf
Delivery "1" *-- "1..*" DeliveryLine : contains
Delivery "*" -- "1" Order : belongsTo
Delivery "*" -- "1" DeliveryService : handledBy
Order "1" -- "0..1" Invoice : billedBy

@enduml

